"3749d9e9679eb6b1133b0cbfb7ea87729f00df807feeeb786f6b5d17d29de4da","request_version":1,"registry_version":1,"request_row_count":2,"request_row_digest":"f6260dbfab8abc87141dc30a40bb05bf"},{"kind":"manual","number":126,"status":"posted","row_count":3,"request_id":"bb0b84d4-3c2a-4b6f-8fe1-e72a3f4bcf22","row_digest":"6cf3410941277cd47c03160dc83ab932","merchant_id":"fdbac4ff-231d-5f41-b09d-91cdc0ca1c62","registry_id":"4139d5f8-3094-4967-ae4d-fdd00668326e","total_cents":70984200,"payment_date":"2026-10-20","source_sha256":"2c0fb19074b29452d8f41f49eb1f93d33d1858522159faf7fe2a2c310331bbc6","request_version":1,"registry_version":1,"request_row_count":3,"request_row_digest":"250147e2c163f27f401559305b2b814d"},{"kind":"manual","number":130,"status":"posted","row_count":2,"request_id":"b9b06e57-9316-4fc1-9057-6806828ed3fa","row_digest":"0153c76a0739a20465382296094ac3b7","merchant_id":"fdbac4ff-231d-5f41-b09d-91cdc0ca1c62","registry_id":"f3474be9-2d7a-490f-811c-5505d7694869","total_cents":49989400,"payment_date":"2026-10-21","source_sha256":"b0c54384693728ecdfd36cd7150c67d10807ff3518254dfdee50b9fbb3afd975","request_version":1,"registry_version":1,"request_row_count":2,"request_row_digest":"1427ec69c27971a7b4e5c4cfb88a5536"},{"kind":"manual","number":132,"status":"posted","row_count":2,"request_id":"a02257c2-0f5d-436c-9f3a-d7e97f144638","row_digest":"228f51425911b0a750f0bf44f74625e1","merchant_id":"fdbac4ff-231d-5f41-b09d-91cdc0ca1c62","registry_id":"b2280331-002c-4df3-916a-7c7724a35456","total_cents":49991400,"payment_date":"2026-10-22","source_sha256":"a7b9d0e7536cc24a116edf2e870d76f520487c174f6ff7abdde43a45fdc8389b","request_version":1,"registry_version":1,"request_row_count":2,"request_row_digest":"b7a0c7e59efc2ae95446ab121afa39be"},{"kind":"manual","number":135,"status":"posted","row_count":2,"request_id":"952f4066-f387-48ad-92c8-d19ded866bd3","row_digest":"2eb716c186f2dda09966a469ffd56246","merchant_id":"1c9e6f0b-4e76-5890-864d-e624b48ea895","registry_id":"46b3f9f6-cfe3-4671-a042-f4bb7a20d9a6","total_cents":46137700,"payment_date":"2026-10-22","source_sha256":"fe67d090cd662bc3c6c2db8d39e4eeb5bb55d36aa1e44e3f775aa3fe0c28ef57","request_version":1,"registry_version":1,"request_row_count":2,"request_row_digest":"825f2b9723f86cfbc2b885e2431de6a4"},{"kind":"manual","number":137,"status":"posted","row_count":1,"request_id":"024c0184-21ae-4d3b-833d-edbd286f3c2c","row_digest":"af87889af3b2acea37c5d390cd5741b8","merchant_id":"38dcc702-da91-5157-9a7a-d779c0fcc5ee","registry_id":"80dae4be-4de6-4bd7-9547-d5ff3bc37e26","total_cents":26953300,"payment_date":"2026-10-22","source_sha256":"8b10c6d2eaf820ab7bc659585b8e08cdd1c1182e946b179d6c6bec7094842156","request_version":1,"registry_version":1,"request_row_count":1,"request_row_digest":"2cd387ffe25680f021ed7e33b4b61e95"},{"kind":"manual","number":139,"status":"posted","row_count":2,"request_id":"f49b0b9e-2513-4154-929c-198a9e8c8e4f","row_digest":"13ee59834e356f5dd81fdf47e80a552d","merchant_id":"da1e2447-2611-5abe-8521-3e1ab8c76c18","registry_id":"7ce497c5-0adb-4270-bd5d-8a01380ec274","total_cents":48221600,"payment_date":"2026-10-22","source_sha256":"5543d6ecbcf1039dc6a1834d3501f3628bf9eb5e5b12ff0e0624b7d85bf793b9","request_version":1,"registry_version":1,"request_row_count":2,"request_row_digest":"0bad080b1d64dc0863775ced95e32eeb"},{"kind":"manual","number":141,"status":"posted","row_count":2,"request_id":"77fd84d6-2eda-46f9-9c9e-1b372447e5de","row_digest":"86fe96ad28309a2ff90e3f8b1844d201","merchant_id":"1c9e6f0b-4e76-5890-864d-e624b48ea895","registry_id":"28fe2e95-dedd-4d81-8580-6fdd47e279d3","total_cents":47283400,"payment_date":"2026-10-23","source_sha256":"2a46adac7f4889ad90ace69ef8d7c9fe50889af0432f2a3cdeee3df8bd0923e3","request_version":1,"registry_version":1,"request_row_count":2,"request_row_digest":"84febbd43edba2e1ab44052c305f61b4"},{"kind":"manual","number":142,"status":"posted","row_count":2,"request_id":"00dba2cf-0109-4009-ba1c-61d92b090aff","row_digest":"680a7dfe413b3d16243162c31289543f","merchant_id":"fdbac4ff-231d-5f41-b09d-91cdc0ca1c62","registry_id":"f0485ebb-0fb2-4a15-8120-cf9f30ea01c7","total_cents":49982400,"payment_date":"2026-10-23","source_sha256":"bdd9735c85a805b87285b5c85e889a092ea4904d51d9dc457c95c5c1472ed285","request_version":1,"registry_version":1,"request_row_count":2,"request_row_digest":"1be2a809fe8c9507880429f4a2a3f25f"}]$approved$::jsonb) AS p(
 registry_id uuid,request_id uuid,number bigint,status text,total_cents bigint,payment_date date,
 merchant_id uuid,kind text,row_count bigint,request_row_count bigint,registry_version integer,
 request_version integer,source_sha256 text,row_digest text,request_row_digest text);
CREATE OR REPLACE FUNCTION pg_temp.history_digest(target regclass) RETURNS text LANGUAGE plpgsql AS $func$
DECLARE digest text;
BEGIN
 EXECUTE format('SELECT md5(COALESCE(string_agg(to_jsonb(x)::text, %L ORDER BY id), %L)) FROM %s x','','',target) INTO digest;
 RETURN digest;
END $func$;
DO $link$
DECLARE
 chief CONSTANT uuid := 'c51891b9-64b1-4a66-81fe-0101351d31f4';
 batch_key CONSTANT text := 'owner:20261026:historical-registry-links:except-5-129';
 item record;
 before_state jsonb;
 after_state jsonb;
 prior_audit integer;
 changed integer;
BEGIN
 IF current_database() NOT IN ('metallist_demo','metallist_registry_links_20261026_testing')
 OR (SELECT max(version) FROM schema_migrations)<>29
 OR NOT EXISTS(SELECT 1 FROM users WHERE id=chief AND role='chief' AND active)
 OR (SELECT count(*) FROM approved_registry_links)<>62
 OR (SELECT count(DISTINCT request_id) FROM approved_registry_links)<>60
 OR EXISTS(SELECT 1 FROM approved_registry_links WHERE number IN (5,129)) THEN
  RAISE EXCEPTION 'Unexpected target, schema, actor or approved scope';
 END IF;
 SELECT count(*) INTO prior_audit FROM audit_events WHERE action='registry_request_link'
   AND detail->>'correction_key'=batch_key;
 IF prior_audit<>0 THEN
  IF prior_audit<>62 OR EXISTS(SELECT 1 FROM approved_registry_links p
    LEFT JOIN registries r ON r.id=p.registry_id
    WHERE r.payment_request_id IS DISTINCT FROM p.request_id
    OR NOT EXISTS(SELECT 1 FROM audit_events a WHERE a.object_id=p.registry_id
      AND a.action='registry_request_link' AND a.detail->>'correction_key'=batch_key
      AND a.detail->>'payment_request_id'=p.request_id::text)) THEN
   RAISE EXCEPTION 'Prior audit conflicts with approved links';
  END IF;
  RAISE NOTICE 'Already applied: 62 links; no changes';
  RETURN;
 END IF;
 IF EXISTS(SELECT 1 FROM postings GROUP BY entry_id
     HAVING sum(CASE side WHEN 'debit' THEN amount_cents ELSE -amount_cents END)<>0) THEN
  RAISE EXCEPTION 'Pre-existing ledger imbalance';
 END IF;
 FOR item IN SELECT * FROM approved_registry_links ORDER BY number LOOP
  IF NOT EXISTS(SELECT 1 FROM registries r JOIN source_documents s ON s.id=r.source_id
    WHERE r.id=item.registry_id AND r.number=item.number AND r.merchant_id=item.merchant_id
    AND r.status=item.status AND r.status IN ('posted','preview') AND r.total_cents=item.total_cents
    AND r.payment_date=item.payment_date AND r.version=item.registry_version
    AND r.payment_request_id IS NULL AND s.kind=item.kind AND s.sha256=item.source_sha256)
  OR NOT EXISTS(SELECT 1 FROM payment_requests q WHERE q.id=item.request_id
    AND q.merchant_id=item.merchant_id AND q.deleted_at IS NULL AND q.version=item.request_version)
  OR EXISTS(SELECT 1 FROM registries r WHERE r.payment_request_id=item.request_id AND r.status<>'deleted')
  OR (SELECT count(*) FROM registry_rows x WHERE x.registry_id=item.registry_id)<>item.row_count
  OR (SELECT sum(amount_cents) FROM registry_rows x WHERE x.registry_id=item.registry_id)<>item.total_cents
  OR (SELECT count(*) FROM payment_request_rows x WHERE x.request_id=item.request_id)<>item.request_row_count
  OR (SELECT md5(string_agg(to_jsonb(x)::text,'' ORDER BY x.id)) FROM registry_rows x WHERE x.registry_id=item.registry_id)<>item.row_digest
  OR (SELECT md5(string_agg(to_jsonb(x)::text,'' ORDER BY x.id)) FROM payment_request_rows x WHERE x.request_id=item.request_id)<>item.request_row_digest THEN
   RAISE EXCEPTION 'Registry % or candidate changed since approved plan',item.number;
  END IF;
  IF EXISTS(SELECT 1 FROM registry_rows x WHERE x.registry_id=item.registry_id
    AND (x.card_id IS NULL OR COALESCE(x.error_code,'')<>''
    OR NOT EXISTS(SELECT 1 FROM payment_request_rows y WHERE y.request_id=item.request_id AND y.card_id=x.card_id))) THEN
   RAISE EXCEPTION 'Registry % has unmatched cards or validation errors',item.number;
  END IF;
  IF item.kind='manual' AND EXISTS(SELECT 1 FROM registry_rows x WHERE x.registry_id=item.registry_id
    AND NOT EXISTS(SELECT 1 FROM payment_request_rows y WHERE y.request_id=item.request_id AND y.card_id=x.card_id
      AND regexp_replace(replace(lower(trim(COALESCE(y.contact_name,y.synthetic_name,''))),'ё','е'),'[[:space:].,;:_/-]+',' ','g')
       =regexp_replace(replace(lower(trim(COALESCE(x.raw->>2,''))),'ё','е'),'[[:space:].,;:_/-]+',' ','g')
      AND COALESCE(x.raw->>2,'')<>'')) THEN
   RAISE EXCEPTION 'Registry % has a contact conflict',item.number;
  END IF;
 END LOOP;
 -- The two split-payment groups, and all singleton groups, must cover their entire request.
 IF EXISTS(SELECT 1 FROM payment_request_rows y WHERE y.request_id IN (SELECT request_id FROM approved_registry_links)
   AND NOT EXISTS(SELECT 1 FROM approved_registry_links p JOIN registry_rows x ON x.registry_id=p.registry_id
      WHERE p.request_id=y.request_id AND x.card_id=y.card_id)) THEN
  RAISE EXCEPTION 'Approved groups do not fully cover their requests';
 END IF;
 IF EXISTS(SELECT p.request_id FROM approved_registry_links p JOIN registry_rows x ON x.registry_id=p.registry_id
   GROUP BY p.request_id HAVING count(*)<>count(DISTINCT x.card_id)) THEN
  RAISE EXCEPTION 'Overlapping payments in approved request groups';
 END IF;
 SELECT jsonb_build_object(
  'entries',pg_temp.history_digest('journal_entries'), 'postings',pg_temp.history_digest('postings'),
  'source_documents',pg_temp.history_digest('source_documents'), 'registry_rows',pg_temp.history_digest('registry_rows'),
  'payment_requests',pg_temp.history_digest('payment_requests'),'payment_request_rows',pg_temp.history_digest('payment_request_rows'),
  'registry_content',(SELECT md5(string_agg((to_jsonb(r)-'payment_request_id'-'version')::text,'' ORDER BY id)) FROM registries r),
  'other_registries',(SELECT md5(string_agg(to_jsonb(r)::text,'' ORDER BY id)) FROM registries r WHERE id NOT IN (SELECT registry_id FROM approved_registry_links))
 ) INTO before_state;
 UPDATE registries r SET payment_request_id=p.request_id,version=r.version+1
   FROM approved_registry_links p WHERE r.id=p.registry_id AND r.payment_request_id IS NULL;
 GET DIAGNOSTICS changed=ROW_COUNT;
 IF changed<>62 THEN RAISE EXCEPTION 'Expected exactly 62 restored links'; END IF;
 INSERT INTO audit_events(id,actor_id,actor_role,channel,action,object_type,object_id,outcome,reason,detail)
 SELECT gen_random_uuid(),chief,'chief','owner_chat','registry_request_link','registry',p.registry_id,'success',
  'Owner approved all historical registry links from the report except registries 5 and 129.',
  jsonb_build_object('correction_key',batch_key,'authorization','Explicit owner request in Codex chat on 2026-10-26',
   'registry_number',p.number,'prior_payment_request_id',NULL,'payment_request_id',p.request_id,
   'prior_version',p.registry_version,'version',p.registry_version+1,
   'ledger_changed',false,'source_changed',false,'status_changed',false,
   'basis','Same merchant and internal card IDs; manual source contacts match request snapshots; split groups cover disjoint full card sets')
 FROM approved_registry_links p;
 SELECT jsonb_build_object(
  'entries',pg_temp.history_digest('journal_entries'), 'postings',pg_temp.history_digest('postings'),
  'source_documents',pg_temp.history_digest('source_documents'), 'registry_rows',pg_temp.history_digest('registry_rows'),
  'payment_requests',pg_temp.history_digest('payment_requests'),'payment_request_rows',pg_temp.history_digest('payment_request_rows'),
  'registry_content',(SELECT md5(string_agg((to_jsonb(r)-'payment_request_id'-'version')::text,'' ORDER BY id)) FROM registries r),
  'other_registries',(SELECT md5(string_agg(to_jsonb(r)::text,'' ORDER BY id)) FROM registries r WHERE id NOT IN (SELECT registry_id FROM approved_registry_links))
 ) INTO after_state;
 IF before_state IS DISTINCT FROM after_state THEN RAISE EXCEPTION 'History or non-link metadata changed'; END IF;
 RAISE NOTICE 'Applied 62 links to 60 requests, created 62 audit events; history digests unchanged: %',after_state;
END $link$;
COMMIT;
